CREATE TABLE invoices (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, direction TEXT NOT NULL, series TEXT, number TEXT NOT NULL, issue_date TEXT NOT NULL, due_date TEXT,
  currency TEXT DEFAULT 'RON', partner_id INTEGER, partner_name TEXT, partner_cui TEXT, net REAL NOT NULL DEFAULT 0, vat REAL NOT NULL DEFAULT 0, total REAL NOT NULL,
  order_id INTEGER, source TEXT DEFAULT 'manual', file_id TEXT, file_name TEXT, status TEXT NOT NULL DEFAULT 'activa', notes TEXT, created TEXT, created_by TEXT
);
CREATE TABLE invoice_lines (id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES invoices(id), name TEXT NOT NULL, unit TEXT, qty REAL, price REAL, vat_pct REAL, value REAL);
CREATE TABLE bank_statements (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, file_name TEXT, file_id TEXT, currency TEXT DEFAULT 'RON', date_from TEXT, date_to TEXT,
  opening REAL, closing REAL, tx_count INTEGER DEFAULT 0, imported_at TEXT, imported_by TEXT
);
CREATE TABLE bank_txs (
  id INTEGER PRIMARY KEY, statement_id INTEGER NOT NULL REFERENCES bank_statements(id), company_id INTEGER NOT NULL, tx_date TEXT NOT NULL, partner TEXT, descr TEXT,
  credit REAL DEFAULT 0, debit REAL DEFAULT 0, balance REAL, hash TEXT, status TEXT NOT NULL DEFAULT 'nepotrivita', category TEXT, note TEXT
);
CREATE INDEX bank_txs_hash ON bank_txs (company_id, hash);
CREATE TABLE cash_entries (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, entry_date TEXT NOT NULL, kind TEXT NOT NULL, number TEXT NOT NULL,
  amount REAL NOT NULL, partner_id INTEGER, partner_name TEXT, explanation TEXT, status TEXT NOT NULL DEFAULT 'activa', created TEXT, created_by TEXT
);
CREATE TABLE allocations (
  id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES invoices(id), tx_id INTEGER, cash_id INTEGER, kind TEXT NOT NULL, amount REAL NOT NULL,
  note TEXT, created TEXT, created_by TEXT
);
